def main():
 assert read(EXP/'CPU_AUDIT.json')['state']=='PASSED';s=read(EXP/'DIAGNOSTIC_SUMMARY.json');f=read(EXP/'FUSION_SUMMARY.json');v=read(EXP/'VISUAL_SAME_INSTANCES_SUMMARY.json');p=read(EXP/'SOURCE_PRIOR_AUDIT.json')
 d={'state':'completed_offline_diagnosis_audited','visual_wrong_preferences_confirmed_in_blind_subset':4,'visual_strict_correct':15,'visual_ties':2,'visual_unresolved':3,'assistant_singleannotator_not_expert_gold':True,'correct_image_final_other_support_after_fusion':2,'correct_image_unmapped_zero_escape':1,'point_support_not_external_calibration_or_literal_identity_gold':True,'standalone_2Dto3D_other_instance_misbinding_confirmed':False,'mapping_not_exonerated_globally':True,'source_prior_firstnoun_readout_verified_n':528,'with_pool':387,'no_pool':141,'original_unmapped_selection_with_pool':34,'Q64_unmapped_selection_with_pool':1,'Q64_mapped_only_changes_IoU':False,'OLD400_mapped_only_gain_pp':s['readout_effects']['OLD400_mapped_competition_only']['balanced_gain_pp'],'ALL528_mapped_only_gain_pp':s['readout_effects']['ALL528_mapped_competition_only']['balanced_gain_pp'],'all_analysis_posthoc_not_new_confirmation':True,'new_G_adopted':False,'no_TTA_or_new_Qwen_grounder_forward':True,'no_new_GPU_queued':True}
 dump(EXP/'DECISION.json',d);dump(EXP/'FINAL_CODE_SNAPSHOT.json',{'programs':{str(x.relative_to(ROOT)):sha(x) for x in list(BASE.glob('*.py'))+list(EXP.parent.glob('*.py'))},'not_a_preregistration_claim':True})
 lines=['# R28：R27缓存的图文排序—映射—融合分解诊断','','本轮没有新增Qwen/grounding前向、GPU实验、训练或TTA。全部528条沿用R27封存预测与同一Waymo-only源模型。以下是已暴露数据的离线诊断，不是新的跨域确认实验，也没有据此替换旧G。','','## 一、融合零点敏感确实存在，但解释不了全部退化','','528条中387条有映射候选池，141条无池。387条的source第一名全部有映射，因此不能用“source第一名恰好没RGB”解释当前现象。原联合G在有池样本中34次选出未映射候选（Drone21/Quad13）。Q64中实际有1次，但该次改回映射候选前后IoU均0；不是0次。','','对全部映射cue加共同常数c，不改变它们内部的顺序，却会改变与未映射零cue候选的竞争。固定c=-0.5时，528条中120条Top1变化，平均mIoU下降4.205742pp；固定c=+0.25有22条变化。这证实读出对任意零点敏感。另一个区别：若所有映射候选只有同一个非负常数证据，因source赢家已映射，在本批中不会改变Frozen source赢家，不能把泛化假设直接当成当前归因。','','去除未映射候选竞争，或将全部映射cue减去source q0的cue，在当前q0已映射条件下得到相同的映射组赢家。只做此项操作，图文分数、映射和框完全不变：','','| 数据 | 原联合G mIoU% | 映射组内竞争/source-anchor | 差值pp |','|---|---:|---:|---:|']
 for phase in ['OLD400','Q64','ALL528']:
  a=sum(f[phase][pl]['joint_original']['mIoU_percent'] for pl in ['drone','quad'])/2;b=sum(f[phase][pl]['mapped_competition_only']['mIoU_percent'] for pl in ['drone','quad'])/2;lines.append(f'| {phase} | {a:.6f} | {b:.6f} | {b-a:+.6f} |')
 lines+=['','OLD400的0.317953pp回收远小于相对旧G的3.151090pp差距。全部528条该控制有12条改善、7条恶化，其余同IoU；Q64虽换1个query但任务指标不变。均值/中位数置零在ALL528反而下降0.120159pp，所以不能声称随便中心化就能修好。全部固定偏移及负例均保留，未挑最优偏移部署。','','## 二、独立于3D IoU的24条视觉盲核','','从多实例池>=2的输入中，按输入哈希和场景轮转固定24条（每平台12）。候选字母顺序重新打乱，隐藏Qwen分数、source分数、grounding选中结果和GT/IoU，先由助理阅读完整文字与RGB并封存判断，再解盲。显示的候选框来自独立MaskRCNN，不能把“隐藏模型输出”误读成没有检测候选。单一助理视觉复核，不是外部专家金标，不能据此宣称全数据集身份准确率。','','21条可给出暂定身份，3条因遮挡/同类形状歧义保留unknown。按精确分数顺序：','','| 已有图文证据 | 严格排对 | 排错 | 目标与邻物并列 | 身份未定 |','|---|---:|---:|---:|---:|']
 for name in ['crop_scene_joint','scene_base','scene_hires','R26_scene','old_subject_raw_dual']:
  c=v[name];lines.append(f"| {name} | {c.get('correct',0)} | {c.get('incorrect',0)} | {c.get('tie_target_other',0)} | {c.get('visual_unresolved',0)} |")
 lines+=['','联合G的15条严格排对中，B22目标仅高3.4332e-5；4条排错中B17也只是反向2.4796e-5。正确顺序不等于有效强度，微小数值差不应被宣传为可靠纠错。上述数值只做描述，没有变成新门槛。旧主体视觉评分也只排对15条，旧G更高的最终mIoU不能直接归因于其VLM单独更准。','','## 三、沿对应关系追踪正确证据','','对已盲核的目标mask，用全场景最近深度投影和互斥mask归属追踪可见LiDAR点，统计各预测框内来自该目标与其它前景的点。至少5个已归属前景点、目标占比>=.8称target-supported，<=.2称other-supported，混合/稀少保留未知。该支撑标签没有使用GT几何或3D IoU；但它与G共享相机和mask，不是独立外部标定或物理ID真值。','','在15条图像排序正确的观测中：12条最终框仍有目标点支撑；2条最大cue候选支持目标但最终F选其它实例支撑；1条被未映射零cue候选超过。没有在该子集中独立确认“正确mask的最高cue被整条映射到另一个实体”的例子；这不代表映射全局正确。','','映射还存在明确的粒度限制：最高cue通常同时落到6–23个query，中位数14。它们共享同一图像证据，G无法进一步判断这些不同3D框的几何质量，仍依赖source。某些框中心在GT外但可见点支持正确目标，因此不能把中心包含或IoU简单当实例身份。作为另一份辅助核对，21个视觉已定mask中只有12个满足预设的高纯度GT目标框点支撑；其余可能涉及部分观测、框范围、投影/标定或标注差异，未强制判为背景或错配。','','## 四、具体失败链条','','- B02/B04：图像中的橙/棕SUV可以区分，目标mask的3D标注点支撑也较强；Qwen却更偏好远处其它车。source原先支持目标，联合G改选非目标支撑框。此类错误发生在图文排序阶段。','- B08：最大图像偏好与映射cue都指向盲核目标。错误实例source优势0.985556，目标的加权cue优势0.75，最终错误F仍高0.235556。该案例的3D标注点一致性偏弱，保留视觉/标定限制，不称完整物理金标。','- B22：目标与其它SUV的图文差仅3.4332e-5，λ2产生6.8665e-5优势，错误source优势却有0.960810。最终F差0.960741；若只放大λ，需要约27985.6才反转这一对。不能把如此弱的偏好当作可靠监督，也不能据此全局放大学习率/λ。','- B13：图像偏好选对，映射候选内114个可见点支持该目标；但cue=-0.499851，未映射框cue=0，后者胜出且没有对应前景支撑。source-anchor可在不改图像排序或映射的情况下恢复原目标候选。','- B17是负向对照：图文分数极微弱地偏向错误站立者，但source保住了正确坐着的人。盲目让VLM完全覆盖source也会损害已有正确选择。','','## 五、source分不是全文实例后验','',f"缓存528条全部使用首个词表名词token的BBF读出。softmax在每个query的文字token轴上进行，不是在256个实例之间归一化；source分与Qwen二元logodds不属于同一概率空间。已从保存投影重算，最大差{p['BBF_score_replay_max_abs_error']:.9g}，mask完全一致。完整文字仍参与编码，这不证明模型忽略关系，也不把官方读出协议称作新发现的bug。它说明不能把高source分直接理解成全文实例身份的高置信后验。",'','## 六、身份与标注边界','','原始元数据没有可直接用于独立核验的跨模态实例ID，bbox_2d_proj也不是另一份独立像素实例金标。官方流程由3D框投影并结合VLM、人审生成表达；只看投影框不能补足独立身份监督。原始9D目标、7D其它框的几何辅助核对沿用官方first7 yaw-only协议，不重新解释额外字段。','','24条模型文字与对应评分目标的完整词和标点序列一致，差异是官方逗号补空格格式；没有找到这批样本的caption/target表连接错位。盲核标签不在解盲后按GT改写，3条未知全部保留。中心包含代理得到的未定结果和可见点支撑结果分开保存，不能混作真实ID标签。','','## 裁决','','确认存在图文错误偏好、未映射零分竞争、source压过正确cue及名词读出/二元logodds尺度语义不一致。W的多query广播粒度和观测覆盖不足也已量化；全局真实误绑定率仍未建立。现阶段先修偏好可用性与读出接口，再用新观测确认；不新增提示词、分辨率扫描或TTA来掩盖尚未解决的监督问题。所有控制仅是离线诊断，旧G仍为精度参照。','','依据：[3EED官方标注流程](https://project-3eed.github.io/)、本地官方dataset/readout实现与R27封存缓存。完整逐条链路、全部反例与偏移控制见附带JSON/CSV，无原始媒体公开发布。']
 (EXP/'REPORT.md').write_text('\n'.join(lines)+'\n');dump(EXP/'RUN_STATE.json',{'run':'completed','measurement':'CPU_audited_with_explicit_identity_limits','claim':'offline_localization_of_failures_no_new_method_claim','new_model_forward_or_TTA':False});print('FINAL28',d)
if __name__=='__main__':main()
